// Design templates: design-skills/<id>/SKILL.md (frontmatter + guide body) with a card image
// at static/design-previews/<id>.png, regenerated by `pnpm design:previews`.

export interface DesignSummary {
	id: string;
	title: string;
	description: string;
	tags: string[];
	preview: string;
}

export interface Design extends DesignSummary {
	/** The SKILL.md body (without frontmatter), sent to Claude as the design guide. */
	body: string;
}

const files = import.meta.glob<string>('/design-skills/*/SKILL.md', { query: '?raw', import: 'default', eager: true });

/** Minimal frontmatter parser: `key: value` lines and `key: [a, b]` lists. */
export function parseSkill(id: string, raw: string): Design {
	const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);

	if (!match) {
		throw new Error(`design-skills/${id}/SKILL.md: frontmatter가 없습니다`);
	}

	const meta: Record<string, string> = {};

	for (const line of match[1].split(/\r?\n/)) {
		const kv = line.match(/^(\w+):\s*(.*)$/);

		if (kv) {
			meta[kv[1]] = kv[2].trim();
		}
	}

	const list = meta.tags?.match(/^\[(.*)\]$/)?.[1] ?? '';

	return {
		id,
		title: meta.title || id,
		description: meta.description ?? '',
		tags: list.split(',').map((t) => t.trim()).filter(Boolean),
		preview: `/design-previews/${id}.png`,
		body: raw.slice(match[0].length).trim()
	};
}

// Catalog order: the existing gov-portal skill first, the rest alphabetically.
const designs: Design[] = Object.entries(files)
	.map(([path, raw]) => parseSkill(path.split('/').at(-2)!, raw))
	.sort((a, b) => (a.id === 'gov-portal' ? -1 : b.id === 'gov-portal' ? 1 : a.id.localeCompare(b.id)));

export function listDesigns(): DesignSummary[] {
	return designs.map(({ body: _body, ...summary }) => summary);
}

export function getDesign(id: string | null | undefined): Design | null {
	return designs.find((d) => d.id === id) ?? null;
}

/**
 * Validates the drawer's form value: '' (or missing) means "기본", i.e. no template.
 * Returns undefined for an unknown id so the caller can reject the request.
 */
export function resolveDesignChoice(value: FormDataEntryValue | null): string | null | undefined {
	if (value === null || value === '') {
		return null;
	}

	return typeof value === 'string' && getDesign(value) ? value : undefined;
}
